50	+    {
51	+        var trimmedReference = reference.Trim();
52	+        var booking = await dbContext.Bookings
53	+            .Include(b => b.Seats)
54	+            .FirstOrDefaultAsync(b => b.Reference == trimmedReference);
55	+
56	+        if (booking is null)
57	+        {
58	+            return CancelBookingResult.NotFoundResult();
59	+        }
60	+
61	+        if (booking.Status == BookingStatus.Cancelled)
62	+        {
63	+            return CancelBookingResult.AlreadyCancelledResult();
64	+        }
65	+
66	+        await using IDbContextTransaction? transaction = dbContext.Database.IsRelational()
67	+            ? await dbContext.Database.BeginTransactionAsync(System.Data.IsolationLevel.ReadCommitted)
68	+            : null;
69	+
70	+        booking.Status = BookingStatus.Cancelled;
71	+        foreach (var seat in booking.Seats)
72	+        {
73	+            seat.IsActive = false;
74	+        }
75	+
76	+        await dbContext.SaveChangesAsync();
77	+        if (transaction is not null) await transaction.CommitAsync();
78	+
79	+        return CancelBookingResult.Success(await BuildBookingDtoAsync(booking.Id));
80	+    }
